package com.tekwatt.payment.service;import com.tekwatt.payment.dto.*;import com.tekwatt.payment.entity.*;import com.tekwatt.payment.repository.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;@Service @Transactional public class PaymentOperationsService{private final PaymentGatewayConfigRepository gateways;private final WalletRepository wallets;private final WalletEntryRepository entries;private final ScanPayOrderRepository orders;public PaymentOperationsService(PaymentGatewayConfigRepository g,WalletRepository w,WalletEntryRepository e,ScanPayOrderRepository o){gateways=g;wallets=w;entries=e;orders=o;}public GatewayConfigResponse gateway(UUID tenantId,GatewayConfigRequest r){PaymentGatewayConfig c=gateways.findByTenantIdAndProviderIgnoreCase(tenantId,r.provider()).orElseGet(()->new PaymentGatewayConfig(tenantId,r.provider().toUpperCase()));c.update(r.enabled(),r.publicKey(),r.secretKey(),r.upiVpa(),r.payeeName());return GatewayConfigResponse.from(gateways.save(c));}@Transactional(readOnly=true)public List<GatewayConfigResponse>gateways(UUID tenantId){return gateways.findAllByTenantIdOrderByProvider(tenantId).stream().map(GatewayConfigResponse::from).toList();}public Wallet createWallet(CreateWalletRequest r){return wallets.findByTenantIdAndUserId(r.tenantId(),r.userId()).orElseGet(()->wallets.save(new Wallet(r.tenantId(),r.userId(),r.currency().toUpperCase())));}@Transactional(readOnly=true)public List<Wallet>wallets(UUID t){return wallets.findAllByTenantIdOrderByUpdatedAtDesc(t);}@Transactional(readOnly=true)public List<WalletEntry>entries(UUID id){wallet(id);return entries.findAllByWalletIdOrderByCreatedAtDesc(id);}public Wallet adjust(UUID id,WalletAdjustmentRequest r){Wallet w=wallet(id);try{w.adjust(r.amount());}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}entries.save(new WalletEntry(id,r.amount(),w.getBalance(),r.reason(),r.reference()));return w;}public ScanPayOrder createOrder(CreateScanPayOrderRequest r){return orders.save(new ScanPayOrder(r.tenantId(),r.userId(),r.stationId(),r.chargerId(),r.amount(),r.currency().toUpperCase(),r.payload()));}@Transactional(readOnly=true)public List<ScanPayOrder>orders(UUID t){return orders.findAllByTenantIdOrderByCreatedAtDesc(t);}public ScanPayOrder updateOrder(UUID id,UpdateScanPayOrderRequest r){ScanPayOrder o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Scan and Pay order not found"));o.link(r.paymentId(),r.sessionId(),r.status().toUpperCase());return o;}private Wallet wallet(UUID id){return wallets.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Wallet not found"));}}
